style.css:
@-moz-document domain("notion.so") {
.notion-link-token {
	text-decoration: underline !important;
	border-radius: 3px !important;
	padding-left: 6px !important;
	padding-right: 6px!important;
	color: rgb(93, 23, 21) !important;
	background: rgb(255, 226, 221) !important;
}

.notion-link-token:hover {
	text-decoration: underline !important;
	border-radius: 3px !important;
	padding-left: 6px !important;
	padding-right: 6px !important;
	color: rgb(64, 44, 27) !important;
	background: rgb(253, 236, 200) !important;
}

.notion-link-token:visited {
	text-decoration: underline !important;
	border-radius: 3px !important;
	padding-left: 6px !important;
	padding-right: 6px !important;
	color: rgb(28, 56, 41) !important;
	background: rgb(219, 237, 219) !important;
}

span[class^="link-annotation"] {
	border-style: none !important;
	opacity: 1 !important;
}
}
